-- Freedemy — SQLite schema (replaces supabase/schema.sql).
-- Applied automatically on first boot by lib/storage/driver.ts; every statement
-- is guarded, so the file is safe to re-run. Ids are generated by the app layer
-- (lib/storage/builder.ts fills `id` when omitted); timestamps are ISO-8601
-- UTC text, matching what the app already writes with toISOString().
--
-- Row-level security is gone by design: every query through a user-bound
-- client carries `WHERE user_id = ?` (or an ownership subquery) automatically —
-- see the scope rules in lib/storage/builder.ts.

-- ---------------------------------------------------------------------------
-- Local accounts (replaces Supabase auth.users + public.profiles)
-- ---------------------------------------------------------------------------

create table if not exists users (
  id text primary key,
  -- Account picker keys are case-insensitive: "Nafiz" and "nafiz" are the same
  -- account, so a second signup can never shadow the first.
  display_name text not null collate nocase unique,
  password_hash text not null,
  security_question text not null,
  security_answer_hash text not null,
  failed_attempts integer not null default 0,
  locked_until integer,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Per-user preferences: provider, API key, model and endpoint overrides.
create table if not exists user_settings (
  user_id text primary key references users (id) on delete cascade,
  provider text,
  api_key text,
  model text,
  base_url text,
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ---------------------------------------------------------------------------
-- Courses
-- ---------------------------------------------------------------------------

create table if not exists courses (
  id text primary key,
  user_id text not null references users (id) on delete cascade,
  slug text not null,
  title text not null,
  channel text not null default '',
  video_id text not null,
  source_url text not null,
  description text not null default '',
  level text not null default 'Intermediate',
  language text not null default 'python',
  duration_seconds integer not null default 0,
  status text not null default 'queued'
    check (status in ('queued', 'fetching', 'outlining', 'writing', 'ready', 'failed')),
  stage text not null default 'Queued',
  error text,
  -- Rigorous study mode: when on, sections unlock in order (assignment passed)
  -- and each chapter's end exam gates the next chapter.
  rigorous integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unique (user_id, slug),
  unique (user_id, video_id)
);

create index if not exists courses_user_idx on courses (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Playlist courses: one course can span many videos
-- ---------------------------------------------------------------------------

-- One row per video of a playlist course (courses.video_id then holds the
-- playlist id). Single-video courses have no rows here.
create table if not exists course_videos (
  id text primary key,
  course_id text not null references courses (id) on delete cascade,
  position integer not null,
  video_id text not null,
  title text not null default '',
  duration_seconds integer not null default 0,
  status text not null default 'queued',
  error text,
  attempts integer not null default 0,
  unique (course_id, position),
  unique (course_id, video_id)
);

create index if not exists course_videos_course_idx on course_videos (course_id, position);

-- ---------------------------------------------------------------------------
-- Modules → lessons
-- ---------------------------------------------------------------------------

create table if not exists modules (
  id text primary key,
  course_id text not null references courses (id) on delete cascade,
  -- Chapters and sections know which playlist video they play in. Null on
  -- single-video courses, which keep the old behaviour.
  course_video_id text references course_videos (id) on delete cascade,
  position integer not null,
  title text not null,
  summary text not null default '',
  start_seconds integer not null default 0,
  end_seconds integer not null default 0,
  unique (course_id, position)
);

create index if not exists modules_course_idx on modules (course_id, position);
create index if not exists modules_video_idx on modules (course_video_id);

create table if not exists lessons (
  id text primary key,
  course_id text not null references courses (id) on delete cascade,
  module_id text not null references modules (id) on delete cascade,
  course_video_id text references course_videos (id) on delete cascade,
  position integer not null,
  title text not null,
  summary text not null default '',
  start_seconds integer not null default 0,
  end_seconds integer not null default 0,
  key_terms text not null default '[]',
  notes text not null default '[]',
  -- Sections are numbered inside their module, so two modules can both have
  -- a section at position 0.
  unique (module_id, position)
);

create index if not exists lessons_course_idx on lessons (course_id, position);
create index if not exists lessons_module_idx on lessons (module_id, position);
create index if not exists lessons_video_idx on lessons (course_video_id);

-- ---------------------------------------------------------------------------
-- Exercises (multiple choice, short answer, coding tasks)
-- ---------------------------------------------------------------------------

create table if not exists exercises (
  id text primary key,
  course_id text not null references courses (id) on delete cascade,
  lesson_id text not null references lessons (id) on delete cascade,
  position integer not null,
  kind text not null check (kind in ('mcq', 'short', 'code')),
  prompt text not null,
  options text not null default '[]',
  answer_index integer,
  keywords text not null default '[]',
  starter_code text,
  solution text,
  explanation text not null default '',
  misconception text not null default '',
  hint text not null default '',
  language text,
  at_seconds integer not null default 0,
  points integer not null default 1,
  unique (lesson_id, position)
);

create index if not exists exercises_lesson_idx on exercises (lesson_id, position);

-- ---------------------------------------------------------------------------
-- Submissions — every graded attempt, kept for marks and review
-- ---------------------------------------------------------------------------

create table if not exists submissions (
  id text primary key,
  user_id text not null references users (id) on delete cascade,
  course_id text not null references courses (id) on delete cascade,
  lesson_id text not null references lessons (id) on delete cascade,
  exercise_id text not null references exercises (id) on delete cascade,
  answer text not null default '{}',
  score integer not null default 0,
  max_score integer not null default 1,
  passed integer not null default 0,
  feedback text not null default '',
  errors text not null default '[]',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index if not exists submissions_user_idx on submissions (user_id, created_at desc);
create index if not exists submissions_lesson_idx on submissions (user_id, lesson_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Per-lesson progress (best score, attempts, completion)
-- ---------------------------------------------------------------------------

create table if not exists lesson_progress (
  user_id text not null references users (id) on delete cascade,
  course_id text not null references courses (id) on delete cascade,
  lesson_id text not null references lessons (id) on delete cascade,
  score integer not null default 0,
  correct integer not null default 0,
  total integer not null default 0,
  attempts integer not null default 0,
  completed integer not null default 0,
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (user_id, lesson_id)
);

create index if not exists lesson_progress_course_idx on lesson_progress (user_id, course_id);

-- ---------------------------------------------------------------------------
-- Final projects — one capstone per course, plus every submitted attempt.
-- The brief is generated once per course and cached here, so every visit and
-- every review sees the same requirements. A course counts as completed when
-- one of its submissions passed.
-- ---------------------------------------------------------------------------

create table if not exists course_projects (
  id text primary key,
  course_id text not null references courses (id) on delete cascade,
  title text not null,
  brief text not null default '',
  requirements text not null default '[]',
  starter_code text not null default '',
  language text not null default 'python',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unique (course_id)
);

create table if not exists project_submissions (
  id text primary key,
  user_id text not null references users (id) on delete cascade,
  course_id text not null references courses (id) on delete cascade,
  project_id text not null references course_projects (id) on delete cascade,
  code text not null default '',
  score integer not null default 0,
  passed integer not null default 0,
  summary text not null default '',
  checks text not null default '[]',
  errors text not null default '[]',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index if not exists project_submissions_user_idx
  on project_submissions (user_id, course_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Tutor conversations
-- ---------------------------------------------------------------------------

create table if not exists tutor_messages (
  id text primary key,
  user_id text not null references users (id) on delete cascade,
  course_id text not null references courses (id) on delete cascade,
  lesson_id text not null references lessons (id) on delete cascade,
  role text not null check (role in ('user', 'assistant')),
  content text not null,
  at_seconds integer,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index if not exists tutor_messages_thread_idx
  on tutor_messages (user_id, lesson_id, created_at);

-- One rolling summary per student per lesson. When a tutor thread outgrows the
-- prompt budget, the turns older than the verbatim window are folded into this
-- row and `covered_until` marks how far the summary reaches, so the next reply
-- still knows the whole conversation without resending all of it.
create table if not exists tutor_summaries (
  user_id text not null references users (id) on delete cascade,
  lesson_id text not null references lessons (id) on delete cascade,
  summary text not null,
  covered_until text not null,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (user_id, lesson_id)
);

-- ---------------------------------------------------------------------------
-- Chapter-end exams (rigorous study mode). One row per student per chapter:
-- `questions` caches the generated MCQs so every retake asks the same paper,
-- while best_score/attempts record the runs. Only a passed exam (>= 80%)
-- opens the next chapter.
-- ---------------------------------------------------------------------------

create table if not exists chapter_quizzes (
  user_id text not null references users (id) on delete cascade,
  course_id text not null references courses (id) on delete cascade,
  module_id text not null references modules (id) on delete cascade,
  questions text not null default '[]',
  best_score integer not null default 0,
  attempts integer not null default 0,
  passed integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (user_id, module_id)
);

create index if not exists chapter_quizzes_course_idx on chapter_quizzes (user_id, course_id);

-- ---------------------------------------------------------------------------
-- Model usage log — server-only (written through the admin client).
-- ---------------------------------------------------------------------------

create table if not exists ai_usage (
  id integer primary key,
  user_id text references users (id) on delete set null,
  course_id text references courses (id) on delete set null,
  kind text not null,
  model text not null,
  prompt_tokens integer,
  completion_tokens integer,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create index if not exists ai_usage_created_idx on ai_usage (created_at desc);
